"""Direct 3:1 and 5:1 quad blocks for different even separator cap counts.

Replace a selected cap-adjacent chart quad with four or seven quads. A 5:1
block nests a second 3:1 block inside the first; it adds four cap vertices and
four interior vertices. All other chart vertices remain exact. No triangles,
boundary removal or pavement resampling is used.
"""
from . import boundary_quad_bridge_nodes as bridge


def rank(g, u, base, count):
    """Piecewise-linear cap rank with evenly distributed odd-count intervals."""
    at = g.math('MULTIPLY', u, base); low = g.math('FLOOR', at)
    extra = g.math('MULTIPLY', .5, g.math('SUBTRACT', count, base))
    def before(i):
        return g.math('FLOOR', g.math('DIVIDE', g.math('MULTIPLY', i, extra), base))
    first = before(low); last = before(g.math('ADD', low, 1.))
    return g.math('ADD', at, g.math('MULTIPLY', 2., g.math('ADD', first,
        g.math('MULTIPLY', g.math('SUBTRACT', at, low), g.math('SUBTRACT', last, first)))))


def _integer_rank(g, index, base, count):
    """Exact rank of an integer base-cap boundary, before template selection.

    Avoid dividing the integer index by base and multiplying it back inside
    rank(). That round trip can produce e.g. a 2.999998 interval difference;
    Blender truncates it when storing INT, omitting its 3:1 replacement.
    Bounded integer products and Floor keep the discrete count discrete.
    """
    extra = g.math('MULTIPLY', .5, g.math('SUBTRACT', count, base))
    before = g.math('FLOOR', g.math('DIVIDE', g.math('MULTIPLY', index, extra), base))
    return g.math('ADD', index, g.math('MULTIPLY', 2., before))


def construct(g, geometry, length, width, head, tail):
    base = g.math('MINIMUM', head, tail)
    different = g.compare(head, tail, 'NOT_EQUAL')
    eligible = g.all(g.compare(base, 4., 'GREATER_EQUAL'),
        *(g.compare(g.math('FLOORED_MODULO', count, 2.), 0.) for count in (head, tail)),
        g.compare(g.math('MAXIMUM', head, tail), g.math('MULTIPLY', 5., base), 'LESS_EQUAL'))
    index = g.node('GeometryNodeInputIndex', 'Cap chart face or vertex index').outputs[0]
    pos = g.node('GeometryNodeInputPosition', 'Cap chart coordinate').outputs[0]
    vertices = []; points = []
    for k in range(4):
        corner = g.node('GeometryNodeCornersOfFace', 'Original direct quad corner')
        g.set(index, corner.inputs['Face Index']); corner.inputs['Sort Index'].default_value = k
        vertex = g.node('GeometryNodeVertexOfCorner', 'Existing cap-chart identity')
        g.set(corner.outputs['Corner Index'], vertex.inputs['Corner Index'])
        vertices.append(vertex.outputs['Vertex Index'])
        points.append(g.sample(geometry, pos, vertices[-1], 'FLOAT_VECTOR'))
    chosen = 0.; matches = 0.; divisions = 0.
    for k in range(4):
        a, b = points[k], points[(k+1) % 4]
        u = g.math('DIVIDE', g.math('MINIMUM', g.component(a, 'Y'), g.component(b, 'Y')), width)
        j = g.math('ROUND', g.math('MULTIPLY', u, base))
        for end, count in ((0., head), (length, tail)):
            cap_edge = g.all(g.close(g.component(a, 'X'), end, 1e-6),
                             g.close(g.component(b, 'X'), end, 1e-6))
            first = _integer_rank(g, j, base, count)
            last = _integer_rank(g, g.math('ADD', j, 1.), base, count)
            selected = g.all(cap_edge, g.compare(g.math('SUBTRACT', last, first), 2., 'GREATER_THAN'))
            chosen = g.math('ADD', chosen, g.math('MULTIPLY', float(k), selected))
            matches = g.math('ADD', matches, selected)
            divisions = g.math('ADD', divisions, g.math('MULTIPLY', selected, g.math('SUBTRACT', last, first)))
    selected = g.compare(matches, 1.)
    selected_count = g.stat(geometry, g.math('MULTIPLY', .5,
        g.math('SUBTRACT', divisions, matches)), domain='FACE', output='Sum')
    expected = g.math('MULTIPLY', .5, g.math('ABSOLUTE', g.math('SUBTRACT', head, tail)))
    eligible = g.all(eligible, g.compare(selected_count, expected),
                     g.compare(g.stat(geometry, matches, domain='FACE', output='Max'), 1., 'LESS_EQUAL'))
    tagged = g.store(geometry, '_cap_replace', selected, 'BOOLEAN', 'FACE')
    tagged = g.store(tagged, '_cap_divisions', divisions, 'INT', 'FACE')
    tagged = g.store(tagged, '_cap_face', index, 'INT', 'FACE')
    for k in range(4):
        at = g.math('FLOORED_MODULO', g.math('ADD', chosen, float(k)), 4.)
        tagged = g.store(tagged, '_cap_vertex_' + str(k), bridge._pick(g, at, vertices, 'INT'), 'INT', 'FACE')
    remove = g.node('GeometryNodeDeleteGeometry', 'Replace only selected cap quads'); remove.domain = 'FACE'; remove.mode = 'ALL'
    g.set(tagged, remove.inputs['Geometry']); g.set(g.named('_cap_replace', 'BOOLEAN'), remove.inputs['Selection'])
    # Capture the original identity before deletion changes point indices.
    tagged = g.store(tagged, '_bridge_key', g.xyz(0., index), 'FLOAT_VECTOR')
    g.set(tagged, remove.inputs['Geometry'])
    ids = [g.named('_cap_vertex_' + str(k)) for k in range(4)]
    a, b, d, c = [g.sample(geometry, pos, v, 'FLOAT_VECTOR') for v in ids]
    added = []
    for ratio in (3, 5):
        seeds = g.node('GeometryNodeMeshToPoints', str(ratio)+':1 cap transition records'); seeds.mode = 'FACES'
        g.set(tagged, seeds.inputs['Mesh'])
        g.set(g.compare(g.named('_cap_divisions'), ratio), seeds.inputs['Selection'])
        if ratio == 3:
            p1 = bridge._mix(g, a, b, 1./3.); p2 = bridge._mix(g, a, b, 2./3.)
            p6 = bridge._mix(g, p1, bridge._mix(g, c, d, 1./3.))
            p7 = bridge._mix(g, p2, bridge._mix(g, c, d, 2./3.))
            points = [a, p1, p2, b, c, d, p6, p7]
            original_corners = ((0, 0), (3, 1), (5, 2), (4, 3))
            faces = ((0, 1, 6, 4), (1, 2, 7, 6), (2, 3, 5, 7), (6, 7, 5, 4))
        else:
            # First transition has cap interval proportions 1:3:1. Its
            # middle child receives another direct 3:1 transition. This
            # supplies five equal cap steps without a fan or zero-area cells.
            points = [a]+[bridge._mix(g, a, b, k/5.) for k in range(1,5)]+[b,c,d]
            q1 = bridge._mix(g, points[1], bridge._mix(g, c, d, 1./5.))
            q4 = bridge._mix(g, points[4], bridge._mix(g, c, d, 4./5.))
            r2 = bridge._mix(g, points[2], bridge._mix(g, q1, q4, 1./3.))
            r3 = bridge._mix(g, points[3], bridge._mix(g, q1, q4, 2./3.))
            points += [q1,q4,r2,r3]
            original_corners = ((0,0),(5,1),(7,2),(6,3))
            faces = ((0,1,8,6),(4,5,7,9),(8,9,7,6),(1,2,10,8),
                     (2,3,11,10),(3,4,9,11),(10,11,9,8))
        face_id = g.named('_cap_face')
        keys = [g.xyz(1., face_id, float(k)) for k in range(len(points))]
        for target, original in original_corners: keys[target] = g.xyz(0., ids[original])
        grid = g.node('GeometryNodeMeshGrid', 'Direct quad per transition face')
        grid.inputs['Vertices X'].default_value = 2; grid.inputs['Vertices Y'].default_value = 2
        rows = g.node('GeometryNodeMeshLine', 'Transition face instances'); rows.inputs['Count'].default_value = len(faces)
        prototype = g.node('GeometryNodeInstanceOnPoints', 'Direct quad template')
        g.set(rows.outputs['Mesh'], prototype.inputs['Points']); g.set(grid.outputs['Mesh'], prototype.inputs['Instance'])
        template = g.node('GeometryNodeRealizeInstances', 'Separate direct faces')
        g.set(prototype.outputs['Instances'], template.inputs['Geometry'])
        instance = g.node('GeometryNodeInstanceOnPoints', 'Selected count transitions')
        g.set(seeds.outputs['Points'], instance.inputs['Points']); g.set(template.outputs['Geometry'], instance.inputs['Instance'])
        realized = g.node('GeometryNodeRealizeInstances', 'Carry original corner identities')
        g.set(instance.outputs['Instances'], realized.inputs['Geometry'])
        order = [face[k] for face in faces for k in (0, 3, 1, 2)]
        local = g.math('FLOORED_MODULO', index, 4.*len(faces))
        part = bridge._position(g, realized.outputs['Geometry'], bridge._pick(g, local, [points[k] for k in order]))
        added.append(g.store(part, '_bridge_key', bridge._pick(g, local, [keys[k] for k in order]), 'FLOAT_VECTOR'))
    result, agreement = bridge._weld(g, bridge._join(g, remove.outputs['Geometry'], *added), exact_reference=True)
    key = g.named('_bridge_key', 'FLOAT_VECTOR'); original = g.compare(g.component(key, 'X'), 0.)
    for name in ('_bridge_source_side', '_bridge_source_index'):
        source = g.sample(geometry, g.named(name), g.component(key, 'Y'), 'INT')
        result = g.store(result, name, g.switch(original, -1, source, 'INT'), 'INT')
    count_ok = g.compare(bridge._size(g, result),
        g.math('ADD', bridge._size(g, geometry), g.math('MULTIPLY', 4., expected)))
    count_ok = g.all(count_ok, g.compare(bridge._size(g, result, 'Face Count'),
        g.math('ADD', bridge._size(g, geometry, 'Face Count'), g.math('MULTIPLY', 3., expected))))
    valid = g.all(eligible, agreement, count_ok, bridge._mesh_good(g, result))
    return g.switch(different, geometry, result, 'GEOMETRY'), g.switch(different, True, valid, 'BOOLEAN')
